/*
  FICHEIRO: src/pages/admin5/CreateAdminPage/CreateAdminPage.jsx (VERSÃO CORRIGIDA)
  Remove os campos desnecessários de CPF, Telefone e ONG.
*/
import React, { useState } from 'react';
import ContentWrapper from '../../../components/ui/ContentWrapper/ContentWrapper';
import InputField from '../../../components/ui/InputField/InputField';
import Button from '../../../components/ui/Button/Button';
import api from '../../../api/api';

const CreateAdminPage = () => {
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    password: '',
  });

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prevState => ({ ...prevState, [name]: value }));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      await api.post('/admins', formData);
      alert(`Administrador "${formData.name}" criado com sucesso!`);
      setFormData({ name: '', email: '', password: '' });
    } catch (error) {
      alert(error.response?.data?.message || "Ocorreu um erro.");
    }
  };

  return (
    <ContentWrapper title="Cadastrar Admin Nível 1">
      <form onSubmit={handleSubmit}>
        <InputField label="Nome Completo" name="name" value={formData.name} onChange={handleChange} />
        <InputField label="Email" type="email" name="email" value={formData.email} onChange={handleChange} />
        <InputField label="Senha Provisória" type="password" name="password" value={formData.password} onChange={handleChange} />
        <div style={{maxWidth: '300px'}}>
          <Button type="submit">Cadastrar Administrador</Button>
        </div>
      </form>
    </ContentWrapper>
  );
};

export default CreateAdminPage;
